  kind: "random";
  from: number;
  to: number;
};
type ScriptOperand = {
  kind: "script";
  script: ScriptInput;
};
type ControlVariablesGameDataOperand = {
  kind: "gameData";
  source: "item";
  item: ReferenceValue<"item">;
} | {
  kind: "gameData";
  source: "weapon";
  weapon: ReferenceValue<"weapon">;
} | {
  kind: "gameData";
  source: "armor";
  armor: ReferenceValue<"armor">;
} | {
  kind: "gameData";
  source: "actor";
